haskell
{-# LANGUAGE FlexibleContexts #-}

module Data.Parser.Grempa.Grammar where

import Control.Applicative ((<|>), Alternative(..))
import Control.Monad (join)
import Control.Monad.Fix (mfix)

data Grammar t a = Grammar {
    entry :: Rule t a,
    rules :: [(String, Rule t a)]
}

data Rule t a = Rule {
    productions :: [Production t a]
}

data Production t a = Production {
    action :: [t] -> a,
    symbols :: [Symbol t a]
}

data Symbol t a = Terminal t | NonTerminal String

rule :: String -> [Production t a] -> Grammar t a
rule name prods = Grammar {
    entry = Rule prods,
    rules = []
}

infixl 4 <@>, <@
(<@>) :: (a -> b) -> Symbol t a -> Production t b
f <@> s = Production (\x -> f (action x)) [s]

(<@) :: (a -> b) -> Symbol t a -> Production t b
f <@ s = Production (\_ -> f (action [])) [s]

